import { Controller, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr00604Controller {
  @Patch('/projects/:projectId')
  async updateProject2(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const projectId = req.params['projectId'];
    if (!/^[0-9]+$/.test(projectId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트 ID 형식이 올바르지 않습니다.');
    }
    const name = data['projectName'];
    const status = data['useStatus'];
    if (name !== undefined && name !== null) {
      if (typeof name !== 'string' || name.trim() === '' || name.length > 200) {
        throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트 명칭은 1~200자로 입력해 주세요.');
      }
    }
    if (status !== undefined && status !== null) {
      if (status !== '사용' && status !== '미사용') {
        throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부는 사용 또는 미사용이어야 합니다.');
      }
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)',
        { projectId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트가 존재하지 않습니다.');
      }
      const rows = await db.query(
        `UPDATE project
            SET project_name = COALESCE(:projectName, project_name),
                use_status = COALESCE(:useStatus, use_status),
                updated_at = now()
          WHERE project_id = CAST(:projectId AS bigint)
          RETURNING project_id AS "projectId"`,
        {
          projectId,
          projectName: name ?? null,
          useStatus: status ?? null,
        },
      );
      return rows[0];
    });
  }
}

