import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const BUSINESS_TYPES: [string, string][] = [
  ['고유목적사업', '고유목적사업'],
  ['수익사업', '수익사업'],
  ['공통사업', '공통사업'],
];
const PROJECT_TYPES: [string, string][] = [
  ['공통', '공통'],
  ['직접사업', '직접사업'],
];
const USE_STATUSES: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];

export default function FnSfr00604Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [nameFilter, setNameFilter] = useState('');
  const [typeFilter, setTypeFilter] = useState('');
  const [applied, setApplied] = useState({ name: '', type: '' });
  const [mode, setMode] = useState<'' | 'create' | 'edit'>('');
  const [target, setTarget] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>({});

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/projects', role, undefined, {
        projectName: applied.name,
        businessType: applied.type,
        page,
        size: 20,
      }),
    [applied, page, role],
  );

  const rows = list.data?.items ?? [];

  const setField = (key: string, value: unknown) => {
    setForm({ ...form, [key]: value });
  };

  const openCreate = () => {
    setForm({});
    setTarget(null);
    setMode('create');
  };

  const openEdit = (row: Row) => {
    setTarget(row);
    setForm({
      projectName: row['projectName'],
      useStatus: '사용',
    });
    setMode('edit');
  };

  const close = () => {
    setMode('');
    setTarget(null);
  };

  const submitCreate = async () => {
    const required: [string, string][] = [
      ['projectCode', '프로젝트 코드'],
      ['projectName', '프로젝트 명칭'],
      ['startDate', '시작일'],
      ['endDate', '종료일'],
      ['businessType', '사업 구분'],
      ['projectType', '프로젝트 유형'],
      ['departmentId', '주관부서 ID'],
      ['managerId', '담당자 ID'],
    ];
    const missing = required
      .filter(([key]) => form[key] === undefined || form[key] === '')
      .map(([, label]) => label);
    if (missing.length > 0) {
      throw new Error('필수 항목을 입력해 주세요: ' + missing.join(', '));
    }
    await call('POST', '/projects', role, form);
    notify('프로젝트를 등록했습니다.');
    close();
    list.reload();
  };

  const submitEdit = async () => {
    if (!target) return;
    if (form['projectName'] === '') {
      throw new Error('프로젝트 명칭을 입력해 주세요.');
    }
    await call('PATCH', '/projects/' + String(target['projectId']), role, {
      projectName: form['projectName'],
      useStatus: form['useStatus'],
    });
    notify('프로젝트를 수정했습니다.');
    close();
    list.reload();
  };

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>전체 프로젝트</h2>
        <Num value={list.data?.total ?? 0} />
      </section>
      <section className="box span-12">
        <h2>프로젝트 목록</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ name: nameFilter, type: typeFilter });
          }}
          onReset={() => {
            setNameFilter('');
            setTypeFilter('');
            setPage(0);
            setApplied({ name: '', type: '' });
          }}
        >
          <Field label="프로젝트 명칭">
            <TextInput value={nameFilter} onChange={setNameFilter} />
          </Field>
          <Field label="사업 구분">
            <Select
              value={typeFilter}
              onChange={setTypeFilter}
              options={BUSINESS_TYPES}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={openCreate}>
            프로젝트 등록
          </button>
        </Band>
        <DataTable
          columns={[
            { key: 'projectCode', label: '프로젝트 코드' },
            { key: 'projectName', label: '프로젝트 명칭' },
            {
              key: 'businessType',
              label: '사업 구분',
              render: (r) => <Badge value={r['businessType']} />,
            },
            { key: 'projectType', label: '프로젝트 유형' },
            {
              key: 'startDate',
              label: '시작일',
              render: (r) => <DateText value={r['startDate']} />,
            },
            {
              key: 'endDate',
              label: '종료일',
              render: (r) => <DateText value={r['endDate']} />,
            },
            {
              key: 'amount',
              label: '프로젝트 금액',
              render: (r) => <Num value={r['amount']} />,
            },
            {
              key: 'projectId',
              label: '관리',
              render: (r) => (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    openEdit(r);
                  }}
                >
                  수정
                </button>
              ),
            },
          ]}
          rows={rows}
          onRowClick={openEdit}
          empty="등록된 프로젝트가 없습니다."
        />
        <Pager
          page={list.data?.page ?? 0}
          size={list.data?.size ?? 20}
          total={list.data?.total ?? 0}
          onPage={setPage}
        />
      </section>
      {mode === 'create' && (
        <Drawer title="프로젝트 등록" onClose={close}>
          <Form onSubmit={submitCreate} submit="등록">
            <Field label="프로젝트 코드" required>
              <TextInput value={form['projectCode']} onChange={(v) => setField('projectCode', v)} />
            </Field>
            <Field label="프로젝트 명칭" required>
              <TextInput value={form['projectName']} onChange={(v) => setField('projectName', v)} />
            </Field>
            <Field label="프로젝트 약칭">
              <TextInput
                value={form['projectShortName']}
                onChange={(v) => setField('projectShortName', v)}
              />
            </Field>
            <Field label="관리계좌">
              <TextInput
                value={form['managingAccount']}
                onChange={(v) => setField('managingAccount', v)}
              />
            </Field>
            <Field label="시작일" required>
              <DateInput value={form['startDate']} onChange={(v) => setField('startDate', v)} />
            </Field>
            <Field label="종료일" required>
              <DateInput value={form['endDate']} onChange={(v) => setField('endDate', v)} />
            </Field>
            <Field label="사업 구분" required>
              <Select
                value={form['businessType']}
                onChange={(v) => setField('businessType', v)}
                options={BUSINESS_TYPES}
              />
            </Field>
            <Field label="프로젝트 유형" required>
              <Select
                value={form['projectType']}
                onChange={(v) => setField('projectType', v)}
                options={PROJECT_TYPES}
              />
            </Field>
            <Field label="주관부서 ID" required>
              <LookupSelect
                table="department"
                role={role}
                value={form['departmentId']}
                onChange={(v) => setField('departmentId', v)}
              />
            </Field>
            <Field label="담당자 ID" required>
              <LookupSelect
                table="employee"
                role={role}
                value={form['managerId']}
                onChange={(v) => setField('managerId', v)}
              />
            </Field>
            <Field label="프로젝트 금액">
              <NumberInput value={form['amount']} onChange={(v) => setField('amount', v)} />
            </Field>
            <Field label="프로젝트 목적" wide>
              <TextInput
                multiline
                value={form['purpose']}
                onChange={(v) => setField('purpose', v)}
              />
            </Field>
            <Field label="프로젝트 내용" wide>
              <TextInput
                multiline
                value={form['content']}
                onChange={(v) => setField('content', v)}
              />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'edit' && target && (
        <Drawer title="프로젝트 수정" onClose={close}>
          <Form onSubmit={submitEdit} submit="수정">
            <Field label="프로젝트 코드">
              <span>{String(target['projectCode'] ?? '')}</span>
            </Field>
            <Field label="프로젝트 명칭" required>
              <TextInput value={form['projectName']} onChange={(v) => setField('projectName', v)} />
            </Field>
            <Field label="사용 여부">
              <Select
                value={form['useStatus']}
                onChange={(v) => setField('useStatus', v)}
                options={USE_STATUSES}
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
